module iir_filter(
    input clk,
    input reset,
    input [15:0] x_in,    // 16-bit input
    output reg [15:0] y_out, // 16-bit output
    output reg valid        // Output valid signal
);
    // Coefficients (example values)
    parameter a1 = 16'h1A2B;
    parameter a2 = 16'h1C2D;
    parameter a3 = 16'h1E2F;
    parameter a4 = 16'h2021;
    parameter b0 = 16'h1A2B;
    parameter b1 = 16'h1C2D;
    parameter b2 = 16'h1E2F;
    parameter b3 = 16'h2021;

    reg [15:0] x[0:4];  // Input history
    reg [15:0] y[0:4];  // Output history

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all values
            y_out <= 16'b0;
            valid <= 1'b0;
            x[0] <= 16'b0; 
            y[0] <= 16'b0;
            x[1] <= 16'b0; 
            y[1] <= 16'b0;
            x[2] <= 16'b0; 
            y[2] <= 16'b0;
            x[3] <= 16'b0; 
            y[3] <= 16'b0;
            x[4] <= 16'b0; 
            y[4] <= 16'b0;
        end else begin
            // Shift input history
            x[4] <= x[3]; 
            x[3] <= x[2]; 
            x[2] <= x[1]; 
            x[1] <= x[0]; 
            x[0] <= x_in;

            // Compute the output
            y_out <= (b0 * x[0] + b1 * x[1] + b2 * x[2] + b3 * x[3] - 
                       a1 * y[1] - a2 * y[2] - a3 * y[3] - a4 * y[4]) >> 15;

            // Shift output history
            y[4] <= y[3]; 
            y[3] <= y[2]; 
            y[2] <= y[1]; 
            y[1] <= y[0]; 
            y[0] <= y_out;

            valid <= 1'b1; // Output is valid
        end
    end
endmodule

