module zero_crossing_detector(
    input clk,
    input rst,
    input signal_in,
    output reg crossing
);

    reg signal_in_prev;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crossing <= 0;
            signal_in_prev <= 0;
        end else begin
            crossing <= (signal_in && !signal_in_prev) || (!signal_in && signal_in_prev);
            signal_in_prev <= signal_in;
        end
    end
endmodule

