module ip_checksum (
    input [15:0] data_in,
    input valid,
    input clk,
    input rst,
    output reg [15:0] checksum,
    output reg done
);
    reg [15:0] sum;
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum <= 16'b0;
            count <= 4'b0;
            checksum <= 16'b0;
            done <= 1'b0;
        end else if (valid) begin
            sum <= sum + data_in;
            count <= count + 1;
            if (count == 4'b1111) begin // Assuming we expect 16 words
                checksum <= ~sum; // One's complement
                done <= 1'b1;
                sum <= 16'b0; // Reset sum
                count <= 4'b0; // Reset count
            end
        end else begin
            done <= 1'b0;
        end
    end

endmodule

