module deserializer (
    input wire clk,
    input wire serial_in,
    output reg [7:0] parallel_out
);
    reg [2:0] bit_count;

    always @(posedge clk) begin
        if (bit_count < 8) begin
            parallel_out[bit_count] <= serial_in;
            bit_count <= bit_count + 1;
        end else begin
            bit_count <= 0; // Reset after 8 bits are received
        end
    end
endmodule

