module spi_controller (
    input wire clk,
    input wire cs, // chip select
    input wire mosi, // master out slave in
    output reg [7:0] data_out // parallel data output
);
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    always @(posedge clk or negedge cs) begin
        if (!cs) begin
            // Reset state when chip select is low
            bit_count <= 3'b000;
            shift_reg <= 8'b00000000;
            data_out <= 8'b00000000;
        end else if (bit_count < 3'b111) begin
            // Capture the MOSI data on clock edge
            shift_reg <= {shift_reg[6:0], mosi};
            bit_count <= bit_count + 1;
        end else begin
            // Output the parallel data after 8 bits
            data_out <= shift_reg;
        end
    end
endmodule

