module pitch_detector (
    input wire clk,
    input wire reset,
    input wire audio_signal,
    output reg pitch_detected
);
    reg [3:0] count; // Counter to count zero-crossings
    reg last_audio_signal;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            pitch_detected <= 0;
            last_audio_signal <= 0;
        end else begin
            if (audio_signal != last_audio_signal) begin
                count <= count + 1;
            end
            last_audio_signal <= audio_signal;

            if (count >= 4) begin // Simple threshold for pitch detection
                pitch_detected <= 1;
            end else begin
                pitch_detected <= 0;
            end
        end
    end
endmodule

