module uart_transmitter (
    input wire clk,
    input wire enable,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 16; // Example divide for baud rate
    reg [3:0] bit_counter;
    reg [3:0] state; // 0: idle, 1: start bit, 2-9: data bits, 10: stop bit
    reg [15:0] baud_counter;

    always @(posedge clk) begin
        if (enable && !busy) begin
            busy <= 1;
            state <= 1; // Start transmitting
            baud_counter <= 0;
            tx <= 1; // Idle state is high
            bit_counter <= 0;
        end else if (busy) begin
            baud_counter <= baud_counter + 1;
            if (baud_counter == BAUD_RATE_DIV) begin
                baud_counter <= 0;
                case (state)
                    1: begin // Start bit
                        tx <= 0; // Start bit is low
                        state <= 2;
                    end
                    2: begin // Data bits (bit 0)
                        tx <= data_in[0];
                        bit_counter <= 1;
                        state <= 3;
                    end
                    3: begin
                        tx <= data_in[1];
                        bit_counter <= 2;
                        state <= 4;
                    end
                    4: begin
                        tx <= data_in[2];
                        bit_counter <= 3;
                        state <= 5;
                    end
                    5: begin
                        tx <= data_in[3];
                        bit_counter <= 4;
                        state <= 6;
                    end
                    6: begin
                        tx <= data_in[4];
                        bit_counter <= 5;
                        state <= 7;
                    end
                    7: begin
                        tx <= data_in[5];
                        bit_counter <= 6;
                        state <= 8;
                    end
                    8: begin
                        tx <= data_in[6];
                        bit_counter <= 7;
                        state <= 9;
                    end
                    9: begin
                        tx <= data_in[7];
                        bit_counter <= 8;
                        state <= 10;
                    end
                    10: begin // Stop bit
                        tx <= 1; // Stop bit is high
                        busy <= 0; // Transmission complete
                        state <= 0; // Go back to idle
                    end
                endcase
            end
        end
    end
endmodule

