module SISO_Shift_Register (  
    input clk,  
    input rst,  
    input serial_in,  
    output reg serial_out  
);  
    reg [4:0] shift_reg;  
    integer count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            shift_reg <= 5'b00000;  
            count <= 0;  
            serial_out <= 0;  
        end else begin  
            if (count < 5) begin  
                shift_reg <= {shift_reg[3:0], serial_in};  
                count <= count + 1;  
                serial_out <= 0;  
            end else begin  
                serial_out <= shift_reg[0];  
                shift_reg <= {shift_reg[3:0], 1'b0};  
            end  
        end  
    end  
endmodule

