module md5_hash (
    input clk,
    input reset,
    input [127:0] data_in,
    output reg [31:0] hash_out
);

reg [31:0] block1, block2, block3, block4;
reg [31:0] temp_hash;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        hash_out <= 32'b0;
        temp_hash <= 32'b0;
    end else begin
        // Divide input into four 32-bit blocks
        block1 <= data_in[127:96];
        block2 <= data_in[95:64];
        block3 <= data_in[63:32];
        block4 <= data_in[31:0];

        // Simple hash calculation (sum of blocks)
        temp_hash <= block1 + block2 + block3 + block4;
        hash_out <= temp_hash;
    end
end

endmodule

